// The angle units. Excluded from rounding: `rotate()` runs its argument through
// trig, which turns a truncated digit into a different computed matrix.
const ANGLE_UNITS = new Set(["deg", "grad", "rad", "turn"]);

// A quarter turn in each unit that spells it exactly (CSS Values 4 §8.1), as
// `unit -> the count`. The trig functions are folded only where their argument
// is a whole number of these, which is where sine and cosine are rational.
/** @type {Map<string, number>} */
const QUARTER_TURN_ANGLE = new Map([
	["deg", 90],
	["grad", 100],
	["turn", 0.25]
]);

// Sine, cosine and tangent as `eighth turn from zero -> value`. The eighths
// where the value is irrational are absent — sine and cosine on the odd ones,
// tangent on the asymptotes. Cosine is sine a quarter turn along.
/** @type {Map<number, number>} */
const EIGHTH_TURN_SINE = new Map([
	[0, 0],
	[2, 1],
	[4, 0],
	[6, -1]
]);

/** @type {Map<number, number>} */
const EIGHTH_TURN_COSINE = new Map([
	[0, 1],
	[2, 0],
	[4, -1],
	[6, 0]
]);

/** @type {Map<number, number>} */
const EIGHTH_TURN_TANGENT = new Map([
	[0, 0],
	[1, 1],
	[3, -1],
	[4, 0],
	[5, 1],
	[7, -1]
]);

// What each inverse trig function answers, as `argument -> degrees`, by
// inverting the table above it over that function's principal branch. Every
// other argument is transcendental and leaves the call written out.
/** @type {Map<number, number>} */
const ARC_SINE_DEGREES = new Map([
	[-1, -90],
	[0, 0],
	[1, 90]
]);

/** @type {Map<number, number>} */
const ARC_COSINE_DEGREES = new Map([
	[-1, 180],
	[0, 90],
	[1, 0]
]);

/** @type {Map<number, number>} */
const ARC_TANGENT_DEGREES = new Map([
	[-1, -45],
	[0, 0],
	[1, 45]
]);

// The reader that needs a table, built once here — `mathPrimitives` knows the
// arithmetic of an eighth turn but not which units spell one.
const readEighthTurn = eighthTurnReader(QUARTER_TURN_ANGLE);

// What folding each math function comes down to, as
// `name -> { read, apply, result, table }`: how its arguments are read, which
// arithmetic runs, and the unit the answer carries. `read` and `apply` are the
// functions themselves, so `lib/css/syntax.js` drives the fold while naming
// neither a math function nor an arithmetic of its own.
/** @type {Map<string, { read: MathArgumentReader, apply: MathOperation, result: string, table: Map<number, number> | null }>} */
const MATH_FUNCTION_FOLD = new Map([
	["abs", { read: readSameUnit, apply: absolute, result: "same", table: null }],
	[
		"acos",
		{
			read: readNumber,
			apply: lookup,
			result: "deg",
			table: ARC_COSINE_DEGREES
		}
	],
	[
		"asin",
		{ read: readNumber, apply: lookup, result: "deg", table: ARC_SINE_DEGREES }
	],
	[
		"atan",
		{
			read: readNumber,
			apply: lookup,
			result: "deg",
			table: ARC_TANGENT_DEGREES
		}
	],
	[
		"atan2",
		{ read: readSameUnit, apply: arcTangent2, result: "deg", table: null }
	],
	["clamp", { read: readSameUnit, apply: clamp, result: "same", table: null }],
	[
		"cos",
		{
			read: readEighthTurn,
			apply: lookup,
			result: "",
			table: EIGHTH_TURN_COSINE
		}
	],
	["exp", { read: readNumber, apply: exponential, result: "", table: null }],
	[
		"hypot",
		{ read: readSameUnit, apply: hypotenuse, result: "same", table: null }
	],
	["log", { read: readNumber, apply: logarithm, result: "", table: null }],
	["max", { read: readSameUnit, apply: maximum, result: "same", table: null }],
	["min", { read: readSameUnit, apply: minimum, result: "same", table: null }],
	["mod", { read: readSameUnit, apply: modulus, result: "same", table: null }],
	["pow", { read: readNumber, apply: power, result: "", table: null }],
	[
		"rem",
		{ read: readSameUnit, apply: remainder, result: "same", table: null }
	],
	["round", { read: readSameUnit, apply: round, result: "same", table: null }],
	["sign", { read: readSameUnit, apply: sign, result: "", table: null }],
	[
		"sin",
		{ read: readEighthTurn, apply: lookup, result: "", table: EIGHTH_TURN_SINE }
	],
	["sqrt", { read: readNumber, apply: squareRoot, result: "", table: null }],
	[
		"tan",
		{
			read: readEighthTurn,
			apply: lookup,
			result: "",
			table: EIGHTH_TURN_TANGENT
		}
	]
]);

